solutions = []
max_val = 5

for x in range(1, max_val + 1):
    for y in range(x, max_val + 1):
        for z in range(y, max_val + 1):
            # Check the equation: x^3 + y^3 + z^3 - x^2*y^2*z^2 = 0
            lhs = x**3 + y**3 + z**3
            rhs = x**2 * y**2 * z**2

            if lhs == rhs:
                solutions.append((x, y, z))
                print(f"Solution found: ({x}, {y}, {z})")

if not solutions:
    print("No solutions found up to x, y, z <= 5.")
else:
    print(f"Total solutions found up to x, y, z <= 5: {len(solutions)}")

